import{_ as t,o,c as s,a4 as i}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"机制一：TUI 渲染（自研 DECSTBM + Alt Screen）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/tui-rendering.md","filePath":"agent-cli/mechanisms/tui-rendering.md"}'),d={name:"agent-cli/mechanisms/tui-rendering.md"};function n(a,e,r,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="机制一-tui-渲染-自研-decstbm-alt-screen" tabindex="-1">机制一：TUI 渲染（自研 DECSTBM + Alt Screen） <a class="header-anchor" href="#机制一-tui-渲染-自研-decstbm-alt-screen" aria-label="Permalink to &quot;机制一：TUI 渲染（自研 DECSTBM + Alt Screen）&quot;">​</a></h1><blockquote><p>对应 <code>src/ui/tui.ts</code>（2099 行）及 <code>src/ui/</code> 下各纯逻辑模块。 这是本项目最复杂、也最容易改坏的一块。<strong>改这里之前务必读完&quot;坑与约束&quot;。</strong></p></blockquote><h2 id="_1-为什么自研-不用-ink-react" tabindex="-1">1. 为什么自研，不用 Ink/React <a class="header-anchor" href="#_1-为什么自研-不用-ink-react" aria-label="Permalink to &quot;1. 为什么自研，不用 Ink/React&quot;">​</a></h2><p>需求要的是&quot;上方固定（状态栏 / 输入框）、下方可滚动（内容区）&quot;的布局，且流式输出不能把界面顶乱。 现成方案（Ink/React）走的是&quot;整棵组件树 diff → 重绘&quot;，难以精确控制滚动区。故直接基于两条 ANSI 能力自研：</p><ul><li><strong>DECSTBM</strong>（<code>ESC1;{bottom}r</code>）：把终端的滚动区域限制为第 1..bottom 行。区域内的滚动<strong>只影响区域内</strong>，区域外（状态栏 / 输入框 / 常驻行 / 浮层）固定不动。</li><li><strong>Alt Screen</strong>（<code>ESC[?1049h</code> / <code>?1049l</code>）：进入备用屏，退出时原样恢复用户原来的终端内容。</li></ul><p>好处是渲染结果退化成<strong>纯数据（行数组）</strong>，可被单测 / 终端模拟器断言 —— 这是本项目&quot;测试代码 &gt; 生产代码&quot;的技术前提。 代价：宽字符（中文 2 列）、wrap-pending、resize 重排都得自己处理。</p><blockquote><p>⚠️ 顺序坑：<code>ALT_SCREEN_EXIT</code> <strong>之后再清屏</strong>（<code>src/ui/tui.ts:412</code> 注释）。顺序反了清的就是 alt screen，退出后主屏会残留垃圾。</p></blockquote><h2 id="_2-屏幕分区-1-based-行号" tabindex="-1">2. 屏幕分区（1-based 行号） <a class="header-anchor" href="#_2-屏幕分区-1-based-行号" aria-label="Permalink to &quot;2. 屏幕分区（1-based 行号）&quot;">​</a></h2><p>设 <code>C = contentRowsFor(rows, floatingRows)</code>（内容区行数）：</p><table tabindex="0"><thead><tr><th>行</th><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><code>1 … C</code></td><td><strong>内容区（可滚动）</strong></td><td>会话消息 / 工具行 / 思考区 / 错误。受 DECSTBM 管辖</td></tr><tr><td><code>C+1</code></td><td>状态栏</td><td><code>statusRow()</code></td></tr><tr><td><code>C+2</code></td><td>输入框上边框</td><td><code>inputTopRow()</code></td></tr><tr><td><code>C+3 … C+5</code></td><td>输入内容窗口（3 行）</td><td><code>inputContentRow(i)</code>；多行输入在此窗口内滚动</td></tr><tr><td><code>C+6</code></td><td>输入框下边框</td><td><code>inputBotRow()</code></td></tr><tr><td><code>C+7</code></td><td><strong>常驻信息区（1 行）</strong></td><td><code>reservedFrom()</code>；权限模式 + 任务摘要（FR-2）</td></tr><tr><td><code>C+8 …</code></td><td><strong>浮层块</strong></td><td><code>floatingFrom()</code> = <code>reservedFrom() + PERSISTENT_ROWS</code>；V-7 规定浮层在常驻行<strong>下方</strong></td></tr></tbody></table><p>24 行终端、无浮层时：<code>C = 17</code> → 状态栏 18、输入框 19..23、常驻行 24。</p><h2 id="_3-布局的唯一公式-硬约束" tabindex="-1">3. 布局的唯一公式（硬约束） <a class="header-anchor" href="#_3-布局的唯一公式-硬约束" aria-label="Permalink to &quot;3. 布局的唯一公式（硬约束）&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// src/ui/tui.ts:216 / 225</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reservedRowsFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(floatingRows </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> PERSISTENT_ROWS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, floatingRows)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contentRowsFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rows, floatingRows </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rows </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> INPUT_ROWS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> STATUS_ROWS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> reservedRowsFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(floatingRows))</span></span></code></pre></div><p>常量：<code>INPUT_ROWS = 5</code>（上边框+3行内容+下边框）、<code>INPUT_CONTENT_ROWS = 3</code>、<code>STATUS_ROWS = 1</code>、<code>PERSISTENT_ROWS = 1</code>、<code>INPUT_PREFIX_WIDTH = 4</code>。</p><ul><li><code>contentRowsFor(24)</code> = <strong>17</strong>；<code>contentRowsFor(24, 3)</code> = <strong>14</strong>（1 行常驻 + 3 行浮层）。</li><li>生产计算（<code>syncSize</code>）与测试断言<strong>都只走这两个函数</strong>，杜绝布局口径分叉。<strong>禁止再写 <code>24 - 5 - 1 - 3</code> 之类的内联算术。</strong></li></ul><h2 id="_4-三种渲染路径" tabindex="-1">4. 三种渲染路径 <a class="header-anchor" href="#_4-三种渲染路径" aria-label="Permalink to &quot;4. 三种渲染路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>触发</th><th>做了什么</th></tr></thead><tbody><tr><td><strong>整区重绘</strong> <code>rerender(top, clearScreen)</code></td><td>resize、关闭浮层、全屏退出后恢复</td><td>清屏（+清 scrollback）→ 从 <code>blocks</code> 重新 <code>flattenBlocks()</code> → 逐行写</td></tr><tr><td><strong>增量写</strong> <code>appendLine(line)</code></td><td>流式 token、新增消息</td><td>内容区末尾追加一行；超出内容区时靠 DECSTBM 让区域自然上滚。<strong>不整区重绘</strong></td></tr><tr><td><strong>固定区/浮层局部写</strong> <code>renderFixed()</code> / <code>paintInfoLine()</code> / <code>renderOverlaySession()</code> / <code>renderFloatingBlock()</code></td><td>状态迁移、tick、按键</td><td>只 <code>cursorTo</code> 到目标行 + <code>clearLine</code> + 写一行/若干行</td></tr></tbody></table><p><strong>性能/稳定性约束（AC-65）</strong>：一次 tick 最多重绘 <strong>≤3 行</strong>（状态栏 + 运行中工具行 + 常驻行），且不含清屏、不含 DECSTBM 重建。面板打开时会多刷浮层块（实测 12 行），这是已知且记录在案的例外。</p><h2 id="_5-浮层-overlay-与-高度恒定-v-5" tabindex="-1">5. 浮层（overlay）与&quot;高度恒定&quot;（V-5） <a class="header-anchor" href="#_5-浮层-overlay-与-高度恒定-v-5" aria-label="Permalink to &quot;5. 浮层（overlay）与&quot;高度恒定&quot;（V-5）&quot;">​</a></h2><p>浮层（审批 / 信任 / 模型 / 面板 / 补全菜单）统一走 [<code>ui/overlay-questions.ts</code> 的 questions 引擎，由 <code>openInteractionOverlay</code> 挂到 TUI。</p><p><strong>高度恒定是硬约束</strong>：某个浮层会话的 <code>height</code> 在创建时冻结，生命周期内<strong>不能变</strong>。 原因：高度一变就会触发<strong>整区重建</strong>（清屏 + 清 scrollback + 从 blocks 全量重推）—— 这是本项目最脆弱的路径（V-5）。</p><p>由此派生出一系列设计：</p><ul><li>面板打开时<strong>快照条目集合与顺序</strong>，之后<strong>只刷新既有条目的内容</strong>（按 id 匹配），不插入/删除 → 条目数不变 → 高度不变。</li><li>弹层的<strong>标题在创建时按当时的 <code>cols</code> 折行并冻结</strong>（<code>titleLines</code>）；渲染时只按当前列宽逐行截断，<strong>不再二次折行</strong> → 任意列宽下行数都等于 <code>height</code>，<code>assertSessionHeight</code> 恒成立。</li><li>二次确认、输入框态等子状态都<strong>复用同一行</strong>（提示行 / 确认行），绝不新增行。</li></ul><h2 id="_6-输入框" tabindex="-1">6. 输入框 <a class="header-anchor" href="#_6-输入框" aria-label="Permalink to &quot;6. 输入框&quot;">​</a></h2><ul><li>模型：<code>ui/input-buffer.ts</code> 的<strong>原子数组</strong>（不是字符串）。图片 / 粘贴占位符是独立元素 → 一次 backspace 整体删除；且图片在消息 content 里的位置与文本位置天然一致。</li><li>渲染：<code>inputLineTexts()</code> 画 3 行；光标处字符反色（<code>INVERSE</code>）。</li><li><code>!</code> 模式（FR-6）：整行高亮（提示符换黄色 <code>!</code>、文本包 YELLOW），<strong>只改行内容不改行数与布局公式</strong>。</li><li>可用列宽 <code>inputTextCols() = cols - INPUT_PREFIX_WIDTH - 2</code>（末尾留 1 列，<strong>避免写到最后一列触发终端自动换行</strong>撑破固定布局）。</li></ul><h2 id="_7-状态栏与唯一定时器" tabindex="-1">7. 状态栏与唯一定时器 <a class="header-anchor" href="#_7-状态栏与唯一定时器" aria-label="Permalink to &quot;7. 状态栏与唯一定时器&quot;">​</a></h2><p><code>ui/status-machine.ts</code>：显式状态机 + <code>Ticker</code>。</p><ul><li>迁移表可单测穷举（7×8 = 56 格全有定义）。</li><li><code>FRAME_INTERVAL_MS = 100</code>；动画帧由 <code>elapsedMs</code> 派生（<strong>无内部帧计数器</strong> → 同一 <code>now</code> 必得同一渲染结果）。</li><li><code>applyStatus()</code> 依据 <code>view.animating</code> <strong>启停唯一定时器</strong>：idle 必停（AC-4）。<code>isActive</code> 可内省，便于断言&quot;零定时器&quot;。</li><li>⚠️ 全屏任务详情打开时 ticker <strong>强制保持运行</strong>（内容实时），关闭时恢复常态策略 —— 见下方&quot;全屏视图&quot;。</li></ul><h2 id="_8-常驻信息区-fr-2" tabindex="-1">8. 常驻信息区（FR-2） <a class="header-anchor" href="#_8-常驻信息区-fr-2" aria-label="Permalink to &quot;8. 常驻信息区（FR-2）&quot;">​</a></h2><p><code>ui/info-line.ts</code> 渲染输入框下方那 1 行：权限模式徽标 + 任务摘要（运行中 N / 共 N）。 数据源由 <code>index.ts</code> <strong>唯一接线</strong>（<code>setTaskSummarySource</code>），每次渲染重读；任务状态变化经 <code>tasks.onChange</code> 事件驱动刷新（<strong>不轮询</strong>）。</p><h2 id="_9-resize" tabindex="-1">9. resize <a class="header-anchor" href="#_9-resize" aria-label="Permalink to &quot;9. resize&quot;">​</a></h2><p><code>onResize()</code>：先 <code>syncSize()</code>（重算 cols/rows/contentRows）→ <code>setScrollRegion()</code>（重建 DECSTBM）→ 若在浮层/全屏则只重绘它，否则整区重绘（清屏 + 清 scrollback，消除终端 reflow 残影）。</p><blockquote><p>⚠️ 测试里模拟 resize 时：必须<strong>先 <code>term.resize()</code> 扩展屏幕</strong>再触发 <code>onResize</code>（<code>testing-rules</code>）。</p></blockquote><h2 id="_10-全屏视图-任务详情" tabindex="-1">10. 全屏视图（任务详情） <a class="header-anchor" href="#_10-全屏视图-任务详情" aria-label="Permalink to &quot;10. 全屏视图（任务详情）&quot;">​</a></h2><p><code>ui/fullscreen.ts</code> 的 <code>TaskDetailView</code>：接管整屏（清屏 + 逐行写满 <code>rows</code> 行）。</p><ul><li><strong>实时</strong>：构造可接收<strong>读取器函数</strong>（而非快照），每次渲染重读状态 / 命令 / 尾部输出。</li><li><strong>跟随</strong>：默认贴底显示最新输出；手动上滚脱离跟随，滚回底部自动恢复。</li><li><strong>只在内容变化时才重绘</strong>（<code>lastFullscreenFrame</code> 帧缓存）——否则 100ms 的 tick 会整屏反复清屏重写，观感就是疯狂闪烁。</li><li>打开期间 ticker 强制运行，关闭时按 <code>animating</code> 恢复。</li></ul><p>⚠️ 全屏期间不要调用会写固定区的方法（<code>renderStatus</code> / <code>paintInfoLine</code>）——全屏已接管整屏，写固定区会覆盖全屏内容。</p><h2 id="_11-坑与约束清单-改这里前必读" tabindex="-1">11. 坑与约束清单（改这里前必读） <a class="header-anchor" href="#_11-坑与约束清单-改这里前必读" aria-label="Permalink to &quot;11. 坑与约束清单（改这里前必读）&quot;">​</a></h2><ol><li><strong>不能碰</strong>的唯一公式、高度恒定、tick 预算、Alt Screen 清屏顺序 —— 见上文各处。</li><li><strong>宽字符</strong>：中文/全角按 2 列。<code>displayWidth()</code> 是唯一实现；<code>truncateTo()</code> 是唯一截断实现（它<strong>原样保留 ANSI 转义序列且不占宽度</strong>）。</li><li><strong>pending wrap</strong>：把内容写到行末最后一列会让终端进入&quot;待换行&quot;状态，下一次写可能触发换行/滚动。故各处都预留 1 列（<code>inputTextCols</code> 减 2、<code>info-line</code> 等）。</li><li><strong>不可信文本必须先净化</strong>（<code>sanitizeForTerminal</code>），且<strong>只能落在内容边界</strong>（如 spec / entry 创建处），<strong>不能落渲染层</strong> —— 渲染层收到的是&quot;样式 + 内容&quot;拼接串，整行净化会剥掉自家高亮。规范见 <code>knowledge/standards/terminal-output-safety.md</code>。</li><li><strong>纯逻辑分层</strong>：<code>ui/*</code> 里除 <code>tui.ts</code> 外都不碰 <code>process.stdin/stdout</code>，只返回&quot;该画什么 / 状态怎么变&quot;。新增 UI 模块必须遵守，否则无法单测。</li><li><strong><code>ui/selector.ts</code> 是死代码</strong>：<code>/model</code> 已改弹层（V-1），<code>mode:&#39;selector&#39;</code> 仅测试可达。不要照着它写新代码。</li></ol><h2 id="_12-怎么测" tabindex="-1">12. 怎么测 <a class="header-anchor" href="#_12-怎么测" aria-label="Permalink to &quot;12. 怎么测&quot;">​</a></h2><ul><li><strong>纯逻辑</strong>：<code>input-buffer</code> / <code>status-machine</code> / <code>overlay-questions</code> / <code>task-panel</code> / <code>completion-menu</code> / <code>text</code> 各自有 vitest 单测。</li><li><strong>端到端</strong>：<code>src/testing/term-sim.ts</code> 模拟终端（解析 CSI、维护屏幕矩阵 + scrollback、支持宽字符与滚动区），驱动真实 <code>TUI</code> 后断言&quot;屏幕内容&quot;与&quot;原始写入串&quot;。详见 <a href="./../testing.html"><code>testing.md</code></a>。</li></ul><blockquote><p>断言技巧：TermSim 只解析部分 CSI（<code>H/G/K/J/r</code>），<strong>SGR（颜色）会被吞掉</strong>。要断言颜色/不可见序列，得看测试里收集的 <code>rawWrites</code>（原始写入串）。</p></blockquote>`,42)])])}const k=t(d,[["render",n]]);export{p as __pageData,k as default};
